            self.receipt, [hop1], POLICY, self.ring, 120, ALPHA, 1, BETA
        )
        payload = hop_payload(hop2)
        self.assertEqual(payload["issuer"], ALPHA)
        self.assertEqual(payload["audience"], BETA)
