import hashlib, hmac, json
from offline_coordination.replication import (
    AuthenticationError, InvalidBatchReceiptError, InvalidReceiptDelegationError,
    delegate_batch_receipt, verify_batch_receipt, verify_batch_receipt_chain,
)

def compact(o): return json.dumps(o, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
def entry(v, s): return {"version": v, "secret": s, "notBefore": 0, "notAfter": 10**9, "revoked": False}
def sign(p, s): return hmac.new(bytes.fromhex(s), compact(p), hashlib.sha256).hexdigest()

POLICY = {"batch": "b", "sites": {"a": {1}}, "threshold": 1}
ring = {n: [entry(1, s)] for n, s in {"coord": "11"*32, "alphä": "22"*32, "beta": "33"*32}.items()}
pol = {"batch": "b", "sites": {"a": [1]}, "threshold": 1}
payload = {"issuer": "coord", "keyVersion": 1, "moment": 100,
           "policy": hashlib.sha256(compact(pol)).hexdigest(),
           "items": [{"id": "i", "digest": "aa"*32, "report": {"error": "x", "id": "i", "result": None, "status": "invalid-proof"}}],
           "version": 1}
receipt = compact({"payload": payload, "signature": sign(payload, "11"*32)})

# non-ASCII audience preserved unescaped
hop1 = delegate_batch_receipt(receipt, [], POLICY, ring, 110, "coord", 1, "alphä")
assert b"alph" in hop1 and b"\\u" not in hop1, hop1
hop2 = delegate_batch_receipt(receipt, [hop1], POLICY, ring, 120, "alphä", 1, "beta")
res = verify_batch_receipt_chain(receipt, [hop1, hop2], POLICY, ring, 200, "beta")
assert list(res) == ["hops", "receipt", "receiptDigest", "target", "version"]
assert res["hops"][0]["audience"] == "alphä"

# self-delegation and repeated domain rejected by the verifier
def mkhop(issuer, secret, aud, up, m):
    p = {"issuer": issuer, "keyVersion": 1, "moment": m, "audience": aud,
         "upstream": hashlib.sha256(up).hexdigest(), "version": 1}
    return compact({"payload": p, "signature": sign(p, secret)})
selfhop = mkhop("coord", "11"*32, "coord", receipt, 110)
try:
    verify_batch_receipt_chain(receipt, [selfhop], POLICY, ring, 200, "coord")
    raise SystemExit("self-delegation accepted")
except InvalidReceiptDelegationError as e:
    assert "hop 0" in str(e)
loop2 = mkhop("alphä", "22"*32, "coord", hop1, 120)
try:
    verify_batch_receipt_chain(receipt, [hop1, loop2], POLICY, ring, 200, "coord")
    raise SystemExit("domain repeat accepted")
except InvalidReceiptDelegationError as e:
    assert "hop 1" in str(e)

# trailing byte / wrong version / wrong upstream
for bad in (hop1 + b"\n",):
    try:
        verify_batch_receipt_chain(receipt, [bad], POLICY, ring, 200, "alphä")
        raise SystemExit("trailing byte accepted")
    except InvalidReceiptDelegationError: pass
p = json.loads(hop1.decode())["payload"]; p["version"] = 2
badv = compact({"payload": p, "signature": sign(p, "11"*32)})
try:
    verify_batch_receipt_chain(receipt, [badv], POLICY, ring, 200, "alphä")
    raise SystemExit("bad version accepted")
except InvalidReceiptDelegationError: pass
p = json.loads(hop1.decode())["payload"]; p["upstream"] = "0"*64
badu = compact({"payload": p, "signature": sign(p, "11"*32)})
try:
    verify_batch_receipt_chain(receipt, [badu], POLICY, ring, 200, "alphä")
    raise SystemExit("bad upstream accepted")
except InvalidReceiptDelegationError: pass

# duplicate-id receipt: InvalidBatchReceiptError even with valid signature
payload2 = dict(payload); payload2["items"] = payload["items"] * 2
r2 = compact({"payload": payload2, "signature": sign(payload2, "11"*32)})
try:
    verify_batch_receipt(r2, POLICY, ring, 200)
    raise SystemExit("duplicate ids accepted")
except InvalidBatchReceiptError as e:
    assert "unique" in str(e)

print("edge-case smoke checks OK")
EOF
